static uint64_t hostclock=0;
double sc_time_stamp(){return double(hostclock*10);}
static constexpr double FMHZ=3579545.0;
static int signed14(unsigned x){return (x&8192)?int(x)-16384:int(x);}
static int clamp13(int x){return std::max(-4096,std::min(4095,x));}
struct Stat{uint64_t n=0,bad=0,first=0,last=0,nzref=0,nzcand=0,clipref=0,clipcand=0;long double sq=0,refsq=0,candsq=0;int peak=0,refpeak=0,candpeak=0;void add(int ref,int cand,uint64_t t){int df=abs(cand-ref);if(df){bad++;if(!first)first=t;last=t;}peak=std::max(peak,df);refpeak=std::max(refpeak,abs(ref));candpeak=std::max(candpeak,abs(cand));sq+=(long double)df*df;refsq+=(long double)ref*ref;candsq+=(long double)cand*cand;n++;nzref+=ref!=0;nzcand+=cand!=0;clipref+=(ref>=4095||ref<=-4096);clipcand+=(cand>=4095||cand<=-4096);}
 void json(std::ostream&o)const{o<<"{\"n\":"<<n<<",\"bad\":"<<bad<<",\"first\":"<<first<<",\"last\":"<<last<<",\"first_seconds\":"<<first/FMHZ<<",\"last_seconds\":"<<last/FMHZ<<",\"peak\":"<<peak<<",\"rms\":"<<(n?sqrt(double(sq/n)):0)<<",\"reference_rms\":"<<(n?sqrt(double(refsq/n)):0)<<",\"candidate_rms\":"<<(n?sqrt(double(candsq/n)):0)<<",\"reference_nonzero\":"<<nzref<<",\"candidate_nonzero\":"<<nzcand<<",\"reference_peak\":"<<refpeak<<",\"candidate_peak\":"<<candpeak<<",\"reference_at_output_rail\":"<<clipref<<",\"candidate_at_output_rail\":"<<clipcand<<"}";}
};
struct Pair{Stat raw,clamped,full_control,reduced_control;void add(int u,int f,int r,uint64_t t){raw.add(f,r,t);clamped.add(clamp13(f),clamp13(r),t);full_control.add(u,f,t);reduced_control.add(u,r,t);}void json(std::ostream&o)const{o<<"{\"raw\":";raw.json(o);o<<",\"clamped\":";clamped.json(o);o<<",\"full_vs_uninterrupted\":";full_control.json(o);o<<",\"reduced_vs_uninterrupted\":";reduced_control.json(o);o<<"}";}};
struct Sim{Vtriad m;Sim(){m.clk=0;m.ena=0;m.reset_n=0;m.hold=0;m.cs_n=1;m.a=0;m.d=0;m.addr=255;m.rd=0;m.wr=0;m.wd=0;m.eval();}void host(){m.clk=0;m.eval();m.clk=1;m.eval();hostclock++;}void tick(unsigned n=1){while(n--){m.ena=1;host();m.ena=0;for(int i=1;i<15;i++)host();}}void regwrite(int reg,int value){m.a=0;m.d=reg;m.cs_n=0;tick();m.cs_n=1;tick(5);m.a=1;m.d=value;m.cs_n=0;tick();m.cs_n=1;tick(150);}uint32_t response(int i){return i==0?m.r0:i==1?m.r1:m.r2;}int audio(int i){return signed14(i==0?m.y0:i==1?m.y1:m.y2);}std::array<uint32_t,100> capture(int instance){std::array<uint32_t,100>x;for(int w=0;w<100;w++){m.addr=w;m.rd=1;tick(3);x[w]=response(instance);}m.rd=0;return x;}};
static std::array<uint32_t,100> mask_for(const std::string&v){std::array<uint32_t,100>x;x.fill(~0u);auto omit=[&](int lo,int hi){for(int i=lo;i<=hi;i++)x[i]=0;};if(v=="control"){}else if(v=="attack")omit(91,92);else if(v=="sine")omit(98,99);else if(v=="writeback")omit(79,79);else if(v=="envelope")omit(31,48);else if(v=="phase")omit(13,30);else if(v=="feedback")omit(49,57);else if(v=="controller"){omit(80,85);x[84]=0x3f;x[85]=0x04000000;}else if(v=="combined"){omit(79,79);omit(91,92);omit(98,99);}else if(v=="macro"){omit(58,99);for(int i:{76,77,78,80,88,90,95})x[i]=~0u;x[81]=0xf;x[84]=0x3f;x[85]=0x04000000;x[87]=0x7fffe000;x[93]=0xfff80000;}else throw std::runtime_error("unknown variant");return x;}
struct Event{uint64_t ce,wanted;unsigned reg,val;};
struct Input{std::vector<Event> es;size_t next=0;int64_t active=-1;uint64_t lastdata=0;std::array<unsigned,64> regs{};Input(const char*file){FILE*f=fopen(file,"rb");if(!f)throw std::runtime_error("event file");char line[200];fgets(line,200,f);while(fgets(line,200,f)){Event e;if(sscanf(line,"%llu,%u,%u,%llu",&e.ce,&e.reg,&e.val,&e.wanted)!=4)throw std::runtime_error("event row");if(e.reg>=64)throw std::runtime_error("event register");es.push_back(e);}fclose(f);}
 void drive(Sim&s,uint64_t ce,std::ofstream*log=nullptr){if(active>=0){auto&e=es[active];if(ce==e.ce+1)s.m.cs_n=1;if(ce==e.ce+11){s.m.a=1;s.m.d=e.val;s.m.cs_n=0;regs[e.reg]=e.val;lastdata=ce;}if(ce==e.ce+12){s.m.cs_n=1;active=-1;}}
 if(next<es.size()&&ce>=es[next].ce){if(ce!=es[next].ce||active>=0)throw std::runtime_error("replay ordering");active=next++;auto&e=es[active];s.m.a=0;s.m.d=e.reg;s.m.cs_n=0;if(log)*log<<ce<<','<<e.reg<<','<<e.val<<'\n';}}
 bool quiet(uint64_t ce)const{return active<0&&ce>lastdata+144&&(next==es.size()||es[next].ce>ce+144);}
};
int main(int argc,char**argv){try{Verilated::commandArgs(argc,argv);if(argc<3)throw std::runtime_error("variant eventfile [saveCE follow continue]");std::string variant=argv[1];uint64_t target=argc>3?strtoull(argv[3],0,10):3579545,follow=argc>4?strtoull(argv[4],0,10):7517045;bool keepWrites=argc>5?atoi(argv[5]):true;auto mask=mask_for(variant);Input input(argv[2]);Sim s;auto start=std::chrono::steady_clock::now();s.tick(5);s.m.reset_n=1;s.tick(1000);if(s.m.ready!=7)throw std::runtime_error("ready");uint64_t save=0;
 for(uint64_t ce=1;;ce++){input.drive(s,ce);s.tick();if(ce>=target&&input.quiet(ce)){save=ce;break;}if(ce>target+3579545)throw std::runtime_error("no quiet SAVE point");}
 Input saved=input;unsigned savedA=s.m.a,savedD=s.m.d,savedCS=s.m.cs_n;s.m.hold=7;s.tick();auto image=s.capture(0);
 int mirrorErrors=0;for(int c=0;c<9;c++){unsigned hi=input.regs[0x20+c],lo=input.regs[0x10+c],iv=input.regs[0x30+c];unsigned expected=((iv>>4)<<18)|((iv&15)<<14)|((hi&32)?8192:0)|((hi&16)?4096:0)|(((hi>>1)&7)<<9)|((hi&1)<<8)|lo;if(expected!=image[c]){fprintf(stderr,"register mirror channel=%d expected=%u actual=%u\n",c,expected,image[c]);mirrorErrors++;}}if(mirrorErrors)throw std::runtime_error("VGM register mirror mismatch");
 s.m.hold=1;uint64_t futureEnd=save+2147727;for(uint64_t ce=save+1;;ce++){input.drive(s,ce);s.tick();if(ce>=futureEnd&&input.quiet(ce)){futureEnd=ce;break;}}
 s.m.hold=7;s.tick();auto stale=s.capture(2);int changed=0,bits=0;for(int w=0;w<100;w++){uint32_t delta=(image[w]^stale[w])&~mask[w];changed+=delta!=0;bits+=__builtin_popcount(delta);s.m.addr=w;s.m.wd=image[w];s.m.wr=2;s.tick();s.m.wr=0;s.tick();if(mask[w]){s.m.wd=(image[w]&mask[w])|(stale[w]&~mask[w]);s.m.wr=4;s.tick();s.m.wr=0;s.tick();}}
 auto full=s.capture(1),red=s.capture(2);{std::ofstream o("state.csv");o<<"word,image,stale,mask,full,reduced\n";for(int w=0;w<100;w++){if(full[w]!=image[w]||red[w]!=((image[w]&mask[w])|(stale[w]&~mask[w])))throw std::runtime_error("game restore readback");o<<w<<','<<image[w]<<','<<stale[w]<<','<<mask[w]<<','<<full[w]<<','<<red[w]<<'\n';}}
 if(variant!="control"&&!changed)throw std::runtime_error("omission not exercised");s.m.rd=0;s.m.addr=255;s.m.a=savedA;s.m.d=savedD;s.m.cs_n=savedCS;s.tick(8);s.m.hold=0;input=saved;
 FILE*audio=fopen("audio.csv","wb"),*internal=fopen("internals.csv","wb");fprintf(audio,"ce,uninterrupted,full,reduced,uninterrupted_clamped,full_clamped,reduced_clamped\n");fprintf(internal,"ce,p0_u,p0_f,p0_r,p1_u,p1_f,p1_r,e0_u,e0_f,e0_r,e1_u,e1_f,e1_r,fb_u,fb_f,fb_r,egstates_u,egstates_f,egstates_r,egkey_u,egkey_f,egkey_r,pgkey_u,pgkey_f,pgkey_r\n");
 Pair total;std::array<Pair,5>segments;std::array<Pair,4>residual;std::array<uint64_t,4>marks={357955,1789773,3579545,7159090};uint32_t previous[3]={s.m.ek0,s.m.ek1,s.m.ek2},prevp[3]={s.m.pk0,s.m.pk1,s.m.pk2};uint64_t on[3]={0},off[3]={0},pon[3]={0},firstOn[3]={0},lastOn[3]={0};std::ofstream ev("events.csv");ev<<"source_ce,register,value\n";size_t pre=input.next;
 for(uint64_t t=1;t<=follow;t++){if(keepWrites)input.drive(s,save+t,&ev);s.tick();int u=s.audio(0),f=s.audio(1),r=s.audio(2);total.add(u,f,r,t);int b=t<=marks[0]?0:t<=marks[1]?1:t<=marks[2]?2:t<=marks[3]?3:4;segments[b].add(u,f,r,t);for(int j=0;j<4;j++)if(t>marks[j]-(uint64_t)ceil(.05*FMHZ)&&t<=marks[j])residual[j].add(u,f,r,t);uint32_t ek[3]={s.m.ek0,s.m.ek1,s.m.ek2},pk[3]={s.m.pk0,s.m.pk1,s.m.pk2};for(int j=0;j<3;j++){unsigned a=__builtin_popcount(ek[j]&~previous[j]);on[j]+=a;off[j]+=__builtin_popcount(previous[j]&~ek[j]);pon[j]+=__builtin_popcount(pk[j]&~prevp[j]);if(a){lastOn[j]=t;if(!firstOn[j])firstOn[j]=t;}previous[j]=ek[j];prevp[j]=pk[j];}
 if(t%72==0||follow<=50000){fprintf(audio,"%llu,%d,%d,%d,%d,%d,%d\n",(unsigned long long)t,u,f,r,clamp13(u),clamp13(f),clamp13(r));fprintf(internal,"%llu,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%llu,%llu,%llu,%u,%u,%u,%u,%u,%u\n",(unsigned long long)t,s.m.p0_0,s.m.p0_1,s.m.p0_2,s.m.p1_0,s.m.p1_1,s.m.p1_2,s.m.e0_0,s.m.e0_1,s.m.e0_2,s.m.e1_0,s.m.e1_1,s.m.e1_2,s.m.fb0,s.m.fb1,s.m.fb2,(unsigned long long)s.m.estates0,(unsigned long long)s.m.estates1,(unsigned long long)s.m.estates2,ek[0],ek[1],ek[2],pk[0],pk[1],pk[2]);}if(t%1000000==0){printf("PROGRESS %.6f seconds\n",t/FMHZ);fflush(stdout);}}
 fclose(audio);fclose(internal);s.m.hold=7;s.tick();auto eu=s.capture(0),ef=s.capture(1),er=s.capture(2);{std::ofstream o("final_state.csv");o<<"word,uninterrupted,full,reduced\n";for(int w=0;w<100;w++)o<<w<<','<<eu[w]<<','<<ef[w]<<','<<er[w]<<'\n';}{std::ofstream k("key_events.json");k<<'[';for(int j=0;j<3;j++){if(j)k<<',';k<<"{\"trajectory\":"<<j<<",\"eg_key_on_bits\":"<<on[j]<<",\"eg_key_off_bits\":"<<off[j]<<",\"pg_key_on_bits\":"<<pon[j]<<",\"first_eg_key_on\":"<<firstOn[j]<<",\"last_eg_key_on\":"<<lastOn[j]<<'}';}k<<"]\n";}
 double wall=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();std::ofstream o("result.json");o<<std::setprecision(16)<<"{\"variant\":\""<<variant<<"\",\"profile\":7,\"point\":"<<(image[78]&127)<<",\"save_ce\":"<<save<<",\"requested_save_ce\":"<<target<<",\"stale_future_ce\":"<<futureEnd<<",\"fm_hz\":"<<FMHZ<<",\"host_per_enable\":15,\"follow\":"<<follow<<",\"seconds\":"<<follow/FMHZ<<",\"changed_words\":"<<changed<<",\"changed_bits\":"<<bits<<",\"register_mirror_errors\":"<<mirrorErrors<<",\"captured_envelopes\":[";for(int w=31;w<=48;w++)o<<(w==31?"":",")<<(image[w]>>23);o<<"],\"external_post_load_writes\":"<<(input.next-pre)<<",\"host_clocks\":"<<hostclock<<",\"wall_seconds\":"<<wall<<",\"total\":";total.json(o);o<<",\"segments\":[";for(int j=0;j<5;j++){if(j)o<<',';segments[j].json(o);}o<<"],\"residual_50ms\":[";for(int j=0;j<4;j++){if(j)o<<',';residual[j].json(o);}o<<"]}\n";printf("PASS GAME variant=%s save=%.6f follow=%.6f changed=%d writes=%u last=%.6f rms=%.6f wall=%.3f\n",variant.c_str(),save/FMHZ,follow/FMHZ,changed,unsigned(input.next-pre),total.raw.last/FMHZ,sqrt(double(total.raw.sq/total.raw.n)),wall);return 0;}catch(const std::exception&e){fprintf(stderr,"FAIL GAME %s\n",e.what());return 1;}}
